// WF1 — Capture des leads recus par EMAIL (leadnettoyage360@gmail.com) -> CRM.
// n8n lit la boite Gmail, extrait les champs et POST le lead au CRM,
// signe HMAC-SHA256 + anti-rejeu (X-Timestamp). Le corps signe DOIT etre
// exactement le corps envoye -> `payload` est serialise une seule fois ici.
// /!\ ADAPTE l'extraction au format EXACT de tes emails de landing page.

const DEFAULT_ACTIVITY = 'nettoyage';
const DEFAULT_SOURCE = 'site_web';
const ACTIVITIES = ['urgence','nettoyage','nettoyage_difficile','enr','renovation','debarras','demenagement','diogene'];
const SOURCES = ['google_ads','meta_ads','site_web','telephone','recommandation'];
const IGNORE_EMAILS = ['leadnettoyage360@gmail.com'];

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const subject = String(j.Subject || j.subject || '');
  const text = String(j.text || j.textPlain || j.snippet || j.html || '');
  const hay = subject + '\n' + text;
  const lines = hay.split(/\r?\n/);

  const field = (...labels) => {
    const low = labels.map((l) => l.toLowerCase());
    for (const line of lines) {
      const idx = line.indexOf(':');
      if (idx === -1) continue;
      const key = line.slice(0, idx).trim().toLowerCase();
      if (low.some((l) => key.includes(l))) {
        const v = line.slice(idx + 1).trim();
        if (v) return v;
      }
    }
    return '';
  };

  const emails = (hay.match(/[\w.+-]+@[\w-]+\.[\w.-]+/g) || [])
    .map((e) => e.toLowerCase())
    .filter((e) => !IGNORE_EMAILS.includes(e));
  const email = (field('email', 'e-mail', 'mail') || emails[0] || '').toLowerCase();

  let phone = (field('telephone', 'tel', 'phone', 'mobile', 'numero') ||
    (hay.match(/(\+?\d[\d\s.\-()]{7,}\d)/) || [])[0] || '').replace(/[^\d+]/g, '');
  if (/^0\d{9}$/.test(phone)) phone = '+33' + phone.slice(1);

  let firstName = field('prenom', 'firstname', 'first name');
  let lastName = field('nom', 'lastname', 'last name', 'name');
  if (!firstName && lastName.includes(' ')) {
    const p = lastName.split(/\s+/); firstName = p.shift(); lastName = p.join(' ');
  }

  let activity = field('activite', 'prestation', 'service', 'metier').toLowerCase();
  if (!ACTIVITIES.includes(activity)) activity = DEFAULT_ACTIVITY;
  let source = field('source').toLowerCase();
  if (!SOURCES.includes(source)) source = DEFAULT_SOURCE;

  const num = (s) => { const n = Number(String(s).replace(',', '.')); return Number.isFinite(n) && n > 0 ? n : null; };
  const surfaceRaw = field('surface', 'm2', 'superficie');
  const surfaceMatch = surfaceRaw.match(/\d+/);
  const surfaceM2 = surfaceMatch ? num(surfaceMatch[0]) : null;

  const lead = {
    external_id: field('external_id', 'id') || ('mail_' + (j.id || Date.now())),
    is_company: false,
    first_name: firstName,
    last_name: lastName,
    company_name: field('societe', 'entreprise', 'company') || null,
    email: email,
    phone: phone,
    address_line: field('adresse', 'address', 'rue'),
    postal_code: field('code postal', 'cp', 'zip'),
    city: field('ville', 'city'),
    activity_slug: activity,
    source_slug: source,
    estimated_amount: num(field('budget', 'montant')),
    surface_m2: surfaceM2,
    type_service: field('type', 'formule') || null,
    notes: field('message', 'commentaire', 'demande', 'description') || text.slice(0, 500),
  };

  const missing = [];
  if (!lead.phone) missing.push('phone');
  if (!(lead.first_name + ' ' + lead.last_name).trim()) missing.push('nom');

  const ts = Math.floor(Date.now() / 1000);
  const payload = JSON.stringify(lead);
  out.push({ json: { ts: ts, payload: payload, signedString: ts + '.' + payload, lead: lead, valid: missing.length === 0, missing: missing.join(', ') } });
}
return out;
